namespace RonSijm.FluidHumidifier.Factories.Transcribe;

public class TranscriptionJobFactory(string resourceName = null, Action<Humidifier.Transcribe.TranscriptionJob> factoryAction = null) : ResourceFactory<Humidifier.Transcribe.TranscriptionJob>(resourceName)
{

    internal List<InnerTranscriptionJobToxicityDetectionSettingsFactory> ToxicityDetectionFactories { get; set; } = [];

    internal InnerTranscriptionJobContentRedactionFactory ContentRedactionFactory { get; set; }

    internal InnerTranscriptionJobSubtitlesFactory SubtitlesFactory { get; set; }

    internal InnerTranscriptionJobMediaFactory MediaFactory { get; set; }

    internal InnerTranscriptionJobSettingsFactory SettingsFactory { get; set; }

    protected override Humidifier.Transcribe.TranscriptionJob Create()
    {
        var transcriptionJobResult = CreateTranscriptionJob();
        factoryAction?.Invoke(transcriptionJobResult);

        return transcriptionJobResult;
    }

    private Humidifier.Transcribe.TranscriptionJob CreateTranscriptionJob()
    {
        var transcriptionJobResult = new Humidifier.Transcribe.TranscriptionJob
        {
            GivenName = InputResourceName,
        };

        return transcriptionJobResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.TranscriptionJob result)
    {
        base.CreateChildren(result);

        result.ToxicityDetection = ToxicityDetectionFactories.Any() ? ToxicityDetectionFactories.Select(x => x.Build()).ToList() : null;
        result.ContentRedaction ??= ContentRedactionFactory?.Build();
        result.Subtitles ??= SubtitlesFactory?.Build();
        result.Media ??= MediaFactory?.Build();
        result.Settings ??= SettingsFactory?.Build();
    }

} // End Of Class

